import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse('{"title":"ADR-0040 — move_prefix resta il rename atomico delle cartelle condivise","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0040-move-prefix-rename-cartelle-condivise.md","filePath":"adr/0040-move-prefix-rename-cartelle-condivise.md"}'),l={name:"adr/0040-move-prefix-rename-cartelle-condivise.md"};function r(n,e,c,d,s,u){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0040-—-move-prefix-resta-il-rename-atomico-delle-cartelle-condivise" tabindex="-1">ADR-0040 — <code>move_prefix</code> resta il rename atomico delle cartelle condivise <a class="header-anchor" href="#adr-0040-—-move-prefix-resta-il-rename-atomico-delle-cartelle-condivise" aria-label="Permalink to &quot;ADR-0040 — `move_prefix` resta il rename atomico delle cartelle condivise&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.2 (2026-11-02): §2.6.4, §3.4.7, §3.5.3, §3.8.5 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-11-01</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§3.4.7 (share e mount, rename della radice condivisa), §3.5.3 (operazioni del commit), §3.8.5 (vault privati); D-04</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no: conferma §3.4.7; precisa solo che un rename che cambia soltanto maiuscole/minuscole è ammesso</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>La review del 2026-11-01 (rilievo <em>move-prefix-unused</em>) ha verificato che il cloud implementa l&#39;operazione <code>move_prefix</code> (rename atomico di una cartella: una revisione <code>move</code> per ogni file sotto il prefisso, nella stessa transazione, e ribasamento di <code>shares.path_prefix</code> con <code>RebasePrefixShares</code>) e il rifiuto <code>SHARE_ROOT_MOVE</code> (un rename &quot;file per file&quot; che porterebbe fuori dalla cartella condivisa il suo ultimo file). Nessun client però li usa: il motore di sync del desktop e il workbench web emettono un rename di cartella come N <code>move</code> singole e non hanno un ramo per <code>SHARE_ROOT_MOVE</code>.</p><p>Conseguenze attuali, su un vault condiviso con una share di cartella:</p><ul><li>il proprietario rinomina <code>Acme</code> in <code>Acme-2024</code>: N−1 <code>move</code> sono accettate, l&#39;ultima è rifiutata con <code>SHARE_ROOT_MOVE</code>. La cartella resta divisa su due percorsi, <code>path_prefix</code> non viene ribasato e i destinatari vedono i file spostati come cancellazioni;</li><li>un rename che cambia solo maiuscole/minuscole (<code>notes</code> → <code>Notes</code>) via <code>move_prefix</code> era rifiutato con un fuorviante <code>PATH_INVALID</code> (&quot;a folder cannot move into itself&quot;), perché le chiavi dei percorsi sono case-folded.</li></ul><p>Il lotto W8 A1 deve decidere se tenere il percorso lato server o rimuoverlo, senza implementare il lato client.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><p><strong>Si tiene <code>move_prefix</code> (e <code>SHARE_ROOT_MOVE</code>) come unico modo di rinominare una cartella condivisa</strong>, come richiede §3.4.7.</p><ul><li>Server (in questo lotto): <code>move_prefix</code> ammette il rename che cambia solo maiuscole/minuscole (stessa chiave, percorso diverso). Resta rifiutato con <code>VALIDATION_FAILED</code> &quot;path is unchanged&quot; se il percorso è identico, e con <code>PATH_INVALID</code> lo spostamento di una cartella dentro sé stessa. Nient&#39;altro cambia nel contratto: nessuna modifica a <code>api/openapi.yaml</code>.</li><li>Client (lavoro successivo, fuori da questo lotto, da pianificare nella roadmap): <ul><li>il motore di sync del desktop e il workbench web riconoscono un rename di cartella (evento del watcher o azione dell&#39;utente) su un vault <strong>condiviso</strong> ed emettono una sola <code>move_prefix</code> invece delle N <code>move</code>. Sui vault privati resta il comportamento attuale (§3.8.5: il server non vede le cartelle);</li><li>un risultato <code>rejected</code> con codice <code>SHARE_ROOT_MOVE</code> fa ripiegare il client su una <code>move_prefix</code> della cartella radice della share (o, se non la può ricostruire, lascia le <code>move</code> in quarantena con un messaggio, senza perdere nulla: D-04);</li><li>un test di contratto desktop↔cloud copre il rename di una cartella condivisa (la share segue la cartella, il destinatario continua a sincronizzare) e il rename solo-maiuscole.</li></ul></li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Rimuovere <code>move_prefix</code> e <code>SHARE_ROOT_MOVE</code>, rifiutando <code>move_prefix</code> con un codice esplicito.</strong> Scartata. Senza un&#39;operazione atomica il ribasamento della share dovrebbe essere dedotto dal server da una sequenza di <code>move</code> singole (eventualmente spezzata su più commit, in ordine arbitrario, con conflitti a metà): un&#39;euristica fragile, che lascerebbe comunque dei destinatari con un mount vuoto o parziale nei casi limite. Il protocollo perderebbe una garanzia di §3.4.7 e servirebbe una deviazione dallo spec, in cambio della sola rimozione di codice già scritto e testato (<code>TestShareRootProtection</code>).</li><li><strong>Ribasare la share quando l&#39;ultimo file lascia il prefisso con una <code>move</code> singola.</strong> Scartata per la stessa ragione: la destinazione dell&#39;ultimo file non dice dove sono finiti gli altri (potrebbero essere stati spostati in cartelle diverse), quindi il nuovo prefisso sarebbe un&#39;ipotesi.</li><li><strong>Togliere solo il rifiuto <code>SHARE_ROOT_MOVE</code>.</strong> Scartata: il rename &quot;file per file&quot; svuoterebbe la share senza ribasarla, e i destinatari vedrebbero sparire tutto senza alcun segnale al proprietario.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Il contratto del cloud non cambia; il rename solo-maiuscole via <code>move_prefix</code> ora funziona (test <code>TestMovePrefixCaseOnlyRename</code>).</li><li>Finché i client non emettono <code>move_prefix</code>, il difetto osservato resta: rinominare dal desktop una cartella condivisa la lascia divisa e l&#39;ultima <code>move</code> torna <code>rejected</code> con <code>SHARE_ROOT_MOVE</code>. Il rischio è un mount incompleto per i destinatari, non una perdita di dati: il proprietario conserva tutti i file e la <code>move</code> rifiutata non tocca né il file né il suo storico.</li><li>Il lavoro client va inserito nella roadmap (registro delle funzioni <code>shared/parity/features.yaml</code> quando verrà implementato) e il relativo test di contratto va aggiunto a quel punto.</li></ul><h2 id="esito" tabindex="-1">Esito <a class="header-anchor" href="#esito" aria-label="Permalink to &quot;Esito&quot;">​</a></h2><p>Lato client implementato nel lotto W8 (extra) nel motore di sync del desktop, che è anche il core WASM del workbench web (<code>apps/desktop/internal/sync/folders.go</code>):</p><ul><li><strong>Vault condiviso, owner:</strong> una cartella rinominata (azione della UI, che passa da <code>Engine.Renamed</code>, o rilevata dalla scansione) diventa una sola <code>move_prefix</code>. Il motore la riconosce quando tutti i file che il server ha sotto la vecchia cartella risultano spostati allo stesso percorso relativo sotto la nuova (o cancellati qui) e la vecchia cartella non esiste più sul disco (confronto esatto del nome, così il rename solo-maiuscole su un file system case-insensitive è riconosciuto); si sceglie la cartella più esterna che soddisfa la regola. Le <code>delete</code> dei file sotto la cartella partono prima della <code>move_prefix</code>. Dopo <code>accepted</code> le righe passano a <code>synced</code> (o <code>local_modified</code> se anche modificate) senza indovinare le revisioni: le <code>move</code> dell&#39;eco, al pull successivo, danno a ogni file la sua revisione; il contenuto modificato parte dopo, sulla revisione nuova. L&#39;id dell&#39;operazione resta nell&#39;outbox per l&#39;idempotenza in caso di risposta persa. Un file con una modifica remota ancora da fondere trattiene l&#39;intero rename (inviarlo a pezzi dividerebbe la cartella).</li><li><strong><code>move_prefix</code> rifiutata</strong> (collisione, <code>FORBIDDEN</code>, <code>NOT_FOUND</code>, …): il round successivo invia le <code>move</code> singole, ciascuna con il proprio esito; non si riprova lo stesso rename né uno più interno.</li><li><strong><code>SHARE_ROOT_MOVE</code> su una <code>move</code> singola</strong> (per esempio l&#39;ultimo file spostato mentre la vecchia cartella resta sul disco): il motore chiede le radici delle condivisioni di cartella del vault (<code>GET /shares?scope=owned</code>, interfaccia opzionale <code>FolderShareRooter</code> del remote) e, se il file ha mantenuto il suo posto sotto il nuovo nome della radice, invia la <code>move_prefix</code> della radice; la condivisione segue. Altrimenti lo spostamento resta in quarantena locale (riga <code>local_moved</code> ferma, <code>last_error</code> con il codice del server), il file resta dove l&#39;utente l&#39;ha messo (D-04) e lo stato della sync (<code>Status.Error</code>, fase <code>idle</code>, senza backoff) spiega che il file è uscito da una cartella condivisa; riportarlo dentro, o spostarlo di nuovo, lo sblocca.</li><li><strong>Vault privato:</strong> invariato, <code>move</code> per file con il path cifrato di nuovo (<code>enc1</code>/<code>enc2</code> secondo il flag e il pin del vault).</li><li><strong>Mount (destinatario editor):</strong> stesso comportamento con path relativi alla radice della condivisione; la radice del mount non è rinominabile (il server risponde <code>SHARE_ROOT_MOVE</code>). In arrivo il server proietta le revisioni: <code>move</code> dentro lo scope, <code>delete</code> per i file usciti, <code>create</code> per quelli entrati; dopo il rename della radice da parte dell&#39;owner i file &quot;rientrano&quot; allo stesso path relativo e, avendo lo stesso blob, il client aggiorna solo la revisione senza riscaricarli.</li><li><strong>Pull:</strong> una serie consecutiva di <code>move</code> che rinomina un&#39;intera cartella locale (nessun altro file sotto la cartella, destinazione libera) si applica con un solo rename della directory e una transazione su <code>sync.db</code>; negli altri casi si applicano le <code>move</code> una per una, con <code>makeRoom</code> sulle collisioni.</li></ul><p>Test: unitari con un server in memoria che modella le regole del cloud (<code>folders_test.go</code>), di integrazione contro il binario cloud reale (<code>e2e_folders_test.go</code>: rename condiviso visto dall&#39;altro dispositivo e dal destinatario, solo-maiuscole, privato, <code>SHARE_ROOT_MOVE</code> recuperato e parcheggiato, modifica concorrente dentro la cartella rinominata) e un caso nel test di contratto (<code>transport/contract_test.go</code>: <code>move_prefix</code> con ribasamento della share, solo-maiuscole, <code>SHARE_ROOT_MOVE</code> per file e dalla radice del mount). Nessuna modifica al server né a <code>api/openapi.yaml</code>.</p><h3 id="integrazione-lato-server-lotto-w8-finale" tabindex="-1">Integrazione lato server (lotto W8, finale) <a class="header-anchor" href="#integrazione-lato-server-lotto-w8-finale" aria-label="Permalink to &quot;Integrazione lato server (lotto W8, finale)&quot;">​</a></h3><p>Le regole della radice condivisa valgono ora anche per <code>move_prefix</code>, sul server (<code>checkShareRoots</code> in <code>services/cloud/internal/sync/ops.go</code>, nessuna modifica al contratto):</p><ul><li>una <code>move_prefix</code> di una cartella <strong>dentro</strong> una condivisione di cartella verso un percorso <strong>fuori</strong> da essa, che porterebbe via tutti i file della condivisione, è rifiutata con <code>SHARE_ROOT_MOVE</code> come la <code>move</code> dell&#39;ultimo file (prima svuotava la condivisione senza ribasarla). Se nella condivisione resta almeno un file è un rename normale: i destinatari vedono le cancellazioni;</li><li>una <code>move_prefix</code> fatta da un editor <strong>attraverso un mount</strong> ribasa le condivisioni annidate nella cartella spostata (prima <code>RebasePrefixShares</code> girava solo per l&#39;owner, lasciando quelle condivisioni su una cartella non più esistente). La radice del mount resta non rinominabile;</li><li>la stessa regola protegge le condivisioni annidate anche dalle <code>move</code> per file fatte da un mount (prima il controllo era saltato per i destinatari). Il dettaglio dell&#39;errore usa i percorsi relativi al mount. Il client, da un mount, non può ricostruire la radice (<code>FolderShareRoots</code> non elenca le condivisioni altrui) e lascia lo spostamento in quarantena con il messaggio, senza perdite (D-04).</li></ul><p>Test di integrazione: <code>TestMovePrefixShareRoots</code> e <code>TestMovePrefixFromMountRebasesNestedShares</code> (<code>services/cloud/test/integration/sharing_test.go</code>).</p>',22)])])}const v=o(l,[["render",r]]);export{p as __pageData,v as default};
